### Description

When looking at the generated schema for fields allowing the MISSING Sentinel the description and title are lost, when the MISSING Sentinel is places after the annotation

This is especially weird as `pattern` is properly handled in this combination in contrast to #12971 

### Example Code

```Python
from typing import Annotated

from pydantic import BaseModel, Field, WithJsonSchema
from pydantic.experimental.missing_sentinel import MISSING


def test_missing_schema_pattern_minimal_without_missing():
    class Model(BaseModel):
        a: Annotated[
            str,
            WithJsonSchema({'type': 'string', 'pattern': '^[a-z]+$'}),
            Field(title='title', description='Something'),
        ]

    assert Model.model_json_schema()['properties'] == {
        'a': {
            'description': 'Something',
            'pattern': '^[a-z]+$',
            'title': 'title',
            'type': 'string',
        }
    }


def test_missing_schema_pattern_minimal_annotated_union():
    class Model(BaseModel):
        a: Annotated[
            str | MISSING,
            WithJsonSchema({'type': 'string', 'pattern': '^[a-z]+$'}),
            Field(title='title', description='Something'),
        ]

    assert Model.model_json_schema()['properties'] == {
        'a': {
            'description': 'Something',
            'pattern': '^[a-z]+$',
            'title': 'title',
            'type': 'string',
        }
    }


def test_missing_schema_pattern_minimal_annotated_in_union():
    class Model(BaseModel):
        a: (
            Annotated[
                str,
                WithJsonSchema({'type': 'string', 'pattern': '^[a-z]+$'}),
                Field(title='title', description='Something'),
            ]
            | MISSING
        )

    assert Model.model_json_schema()['properties'] == {
        'a': {
            'description': 'Something',
            'pattern': '^[a-z]+$',
            'title': 'title',
            'type': 'string',
        }
    }


def test_missing_schema_pattern_minimal_assignment_annotated_in_union():
    class Model(BaseModel):
        a: (
            Annotated[
                str,
                WithJsonSchema({'type': 'string', 'pattern': '^[a-z]+$'}),
            ]
            | MISSING
        ) = Field(title='title', description='Something')

    assert Model.model_json_schema()['properties'] == {
        'a': {
            'description': 'Something',
            'pattern': '^[a-z]+$',
            'title': 'title',
            'type': 'string',
        }
    }


def test_missing_schema_pattern_minimal_assignment_annotated_union():
    class Model(BaseModel):
        a: Annotated[
            str | MISSING,
            WithJsonSchema({'type': 'string', 'pattern': '^[a-z]+$'}),
        ] = Field(title='title', description='Something')

    assert Model.model_json_schema()['properties'] == {
        'a': {
            'description': 'Something',
            'pattern': '^[a-z]+$',
            'title': 'title',
            'type': 'string',
        }
    }
```

